for row in doc.get("items", []):
    if frappe.db.get_value("Item", row.item_code, "custom_approval_status") != "Approved":
        frappe.throw(f"Item {row.item_code} is not yet approved for transactions")

for row in doc.get("items", []):
    if frappe.db.get_value("Item", row.item_code, "custom_approval_status") != "Approved":
        frappe.throw(f"Item {row.item_code} is not yet approved for transactions")

credit_limit_changed = False
if not doc.is_new():
    before = doc.get_doc_before_save()
    if before:
        before_limits = {row.company: row.credit_limit for row in before.get("credit_limits", [])}
        after_limits = {row.company: row.credit_limit for row in doc.get("credit_limits", [])}
        credit_limit_changed = before_limits != after_limits

if doc.has_value_changed("payment_terms") or credit_limit_changed:
    if not frappe.db.exists("Has Role", {"parent": frappe.session.user, "role": "Accounts Manager"}):
        doc.custom_approval_status = "Pending"

customer = frappe.db.get_value(
    "Customer", doc.customer, ["custom_has_sales_issue", "custom_approval_status"], as_dict=True
)

if customer.custom_has_sales_issue and not doc.custom_manager_override:
    frappe.throw("This customer has a flagged sales issue. Sales Manager override required before submission.")

if customer.custom_approval_status in ("Pending", "Rejected") and not doc.custom_manager_override:
    frappe.throw(
        "This customer's credit limit/payment terms change is awaiting Accounts Manager approval. "
